-- SPDX-License-Identifier: GPL-3.0-or-later
-- The rules that learn what Forever has. Nobody knows what is in the game at launch, so Cute ships with what research
-- and the beta showed (Known.lua, generated by gen_known.py: the dungeons with their level ranges, their bosses and the
-- bosses' loot, the enchants per slot, the XP each level takes, the factions, each fact marked with how sure it is) and
-- learns the rest from what guild members meet in play, by the fixed rules below. The seed is a guess the addon can
-- throw away: Rule 0 checks it against the live client at login and marks it stale when the game differs, and every
-- page works with no seed at all (a copy without Known.lua, or one gen_known.py wrote empty).
-- A fact's state: data (from research only), beta (seen in the beta), seen (seen by this guild in play), doubted (the
-- guild's play contradicts it), absent (this client has no such thing), stale (the whole seed no longer matches the
-- game). The model is kept in CuteDB.known.model, built again from the seed, the saved records and what this client
-- met at every login and a few seconds after the guild's play changes it; the first time and who (by GUID) saw each
-- fact carry over from one build of it to the next, so a count never falls as members leave.
-- The thresholds are in one table (RULES). Officers retune them in game (Settings), the values travel with the
-- visibility policy (Policy.lua) and apply the same way, so the guild adapts the rules on launch day without an
-- update. The evidence the rules weigh travels as before: boss kills and dungeon entries in the discoveries pass, the
-- level a member had at a boss's first kill beside it (k<encounterID>, below), the XP a level takes in the hidden xpmax
-- stat, the loot a boss dropped in the labels message (Comm.lua).
local _, C = ...
local R = { version = 0, started = false }
C.Rules = R

R.RULES = { rangeMembers = 5, rangeLow = 0.10, rangeHigh = 0.90, doubtRuns = 3, enchantDoubtDays = 14, enchantDoubtLevel = 30,
  xpAgree = 3, lootDoubtKills = 5, staleShare = 0.30, guideWindow = 3, guideAhead = 5 }
-- every threshold as Settings shows it (a label short enough for the narrow window), the bounds an officer can set it
-- to, how it reads, and what it does in a sentence (the step buttons' tooltip): { name, label, lowest, highest, step,
-- how it reads, what }. A value from the channel outside its bounds is dropped, never clamped
R.TUNE = {
  { "rangeMembers", "Members to learn a range", 1, 40, 1, nil, "Members whose kill levels it takes to learn a dungeon's level range." },
  { "rangeLow", "Range, lower percentile", 0, 0.5, 0.05, "pctile", "A learned range starts at this percentile of the members' kill levels." },
  { "rangeHigh", "Range, upper percentile", 0.5, 1, 0.05, "pctile", "A learned range ends at this percentile of the members' kill levels." },
  { "doubtRuns", "Full runs to doubt a boss", 1, 20, 1, nil, "Full runs of a dungeon that never meet one of the research's bosses before it is doubted; each more boss missing takes as many runs again." },
  { "enchantDoubtDays", "Days to doubt a slot", 1, 90, 1, nil, "Days of members at the enchant level wearing items in a slot, with no enchant seen there, before the research's slot is doubted." },
  { "enchantDoubtLevel", "Enchant level", 1, 60, 1, nil, "From this level the research's enchant slots count as missing, and members this level or more start the doubt clock." },
  { "xpAgree", "Members to agree on XP", 1, 20, 1, nil, "Members who report the same XP for a level before it replaces the research's." },
  { "lootDoubtKills", "Kills to note unseen loot", 1, 50, 1, nil, "Kills of a boss before the research's loot nobody has seen drop is noted." },
  { "staleShare", "Stale when absent over", 0.05, 0.95, 0.05, "pct", "The research is stale when this client lacks more than this share of what it names." },
  { "guideWindow", "Guide: levels near you", 0, 10, 1, nil, "The Guide names the members online within this many levels of yours." },
  { "guideAhead", "Guide: levels ahead", 1, 20, 1, nil, "The Guide lists the dungeons opening within this many levels under Next up." },
}
R.TUNE_BY, R.LOWER = {}, {}
for _, t in ipairs(R.TUNE) do R.TUNE_BY[t[1]] = t; R.LOWER[t[1]:lower()] = t[1] end

local WHO_CAP = 1000 -- members kept per fact (a guild holds a thousand)
local LOOT_CAP = 40  -- items kept per boss from the channel
local SLICE = 50     -- Rule 0's checks per frame
local DAY = 86400

local function count(t) local n = 0; if type(t) == "table" then for _ in pairs(t) do n = n + 1 end end return n end
local function num(v) return type(v) == "number" and v == v and v or nil end
local function known() return C.Stats and C.Stats.Known() or nil end

----------------------------------------------------------------------------
-- the thresholds: the officers' value where one is set (Policy.lua), else the default
----------------------------------------------------------------------------
function R.Valid(name, v)
  local t = R.TUNE_BY[name]
  return t ~= nil and type(v) == "number" and v == v and v >= t[3] - 1e-9 and v <= t[4] + 1e-9
end
function R.Get(name)
  local p = CuteDB and CuteDB.policy
  local v = p and type(p.rules) == "table" and tonumber(p.rules[name]) or nil
  if v and R.Valid(name, v) then return v end
  return R.RULES[name]
end
-- a threshold as Settings and /cute rules show it
function R.Show(name, v)
  v = v or R.Get(name)
  local t = R.TUNE_BY[name]
  if t and t[6] == "pct" then return string.format("%d%%", math.floor(v * 100 + 0.5)) end
  if t and t[6] == "pctile" then
    local n = math.floor(v * 100 + 0.5)
    local tail = (n % 100 >= 11 and n % 100 <= 13) and "th" or ({ [1] = "st", [2] = "nd", [3] = "rd" })[n % 10] or "th"
    return n .. tail
  end
  return tostring(math.floor(v + 0.5))
end
-- who set a threshold: nil for the default, else the GUID the policy names (yours as "me")
function R.SetBy(name)
  local p = CuteDB and CuteDB.policy
  if not (p and type(p.rules) == "table" and p.rules[name] ~= nil and R.Valid(name, tonumber(p.rules[name]))) then return nil end
  local by = type(p.ruleBy) == "table" and p.ruleBy[name] or nil
  return (type(by) == "string" and by ~= "") and by or "?"
end
-- the name of whoever a GUID is, for a line to read
function R.WhoName(guid)
  if guid == nil then return nil end
  if guid == "me" or guid == C.MyGUID() then return C.Roster:MyDisplay() end
  local m = C.Roster.byGuid and C.Roster.byGuid[guid]
  if m and m.name then return C.Short(m.name) end
  -- (no GUID came with it: the officer whose policy holds it)
  local p = CuteDB and CuteDB.policy
  if guid == "?" and p and p.by then return p.mine and C.Roster:MyDisplay() or C.Roster:Display(p.by) end
  return "an officer no longer listed"
end
-- a threshold retuned (here or by the policy): the model follows a few seconds on, your own Missing enchants in one
function R:Retuned()
  self:Dirty()
  if C.Sample and C.Sample.started then C.Sample:Schedule("unenchanted"); C.Sample:Schedule("ready") end
end

----------------------------------------------------------------------------
-- the seed (Known.lua), read once and checked field by field: a file that is absent, empty or partial gives what it
-- has and nothing more
----------------------------------------------------------------------------
local seed -- the seed as the rules read it; false where there is none
local function conf(c) return c == "beta" and "beta" or "data" end
-- a list of kinds of item ("4.6", as Stats.lua's itemKind makes them) as a set; nil where the seed names none
local function kindSet(list)
  if type(list) ~= "table" then return nil end
  local out = {}
  for _, kd in ipairs(list) do if type(kd) == "string" and kd:match("^%d+%.%d+$") then out[kd] = true end end
  return out
end
-- Beside the fixed format the seed may mark a dungeon whose wings share one instance (wings = true, or the wings'
-- names: Scarlet Monastery's four, Dire Maul's three), a boss that is no fight every run meets (optional = true: a
-- rare spawn, an event, a boss a quest spares) and the kinds of item each enchant takes (a list's kinds, beside the
-- slot's). Rule 4 never doubts in the first or the second; the Guide names for a worn item only the enchants that take
-- its kind. A boss the seed names without an encounter id is kept by name, to be matched when the guild meets it
function R.Seed()
  if seed ~= nil then return seed or nil end
  local K = C.Known
  if type(K) ~= "table" then seed = false; return nil end
  local s = { build = type(K.build) == "string" and K.build or nil, generated = type(K.generated) == "string" and K.generated or nil,
    cap = num(K.cap), betaCap = num(K.betaCap), dungeons = {}, bosses = {}, enchants = {}, xp = {}, xpConf = {}, factions = {},
    items = {}, spells = {}, sources = {} }
  for _, src in ipairs(type(K.sources) == "table" and K.sources or {}) do if type(src) == "string" then s.sources[#s.sources + 1] = src end end
  for id, d in pairs(type(K.dungeons) == "table" and K.dungeons or {}) do
    if num(id) and type(d) == "table" and type(d.name) == "string" and d.name ~= "" then
      local e = { id = id, name = d.name, min = num(d.min), max = num(d.max), new = d.new == true, conf = conf(d.conf),
        kind = d.kind == "raid" and "raid" or "party", bosses = {}, named = {},
        wings = (d.wings == true or (type(d.wings) == "table" and next(d.wings) ~= nil)) or nil }
      if e.min and e.max and e.min > e.max then e.min, e.max = e.max, e.min end
      if not (e.min and e.max) then e.min, e.max = nil, nil end
      for _, b in ipairs(type(d.bosses) == "table" and d.bosses or {}) do
        if type(b) == "table" and type(b.name) == "string" and b.name ~= "" then
          if num(b.enc) and not s.bosses[b.enc] then
            local be = { enc = b.enc, name = b.name, conf = conf(b.conf or d.conf), inst = id, order = #e.bosses + 1, loot = {},
              optional = b.optional == true or nil }
            for _, item in ipairs(type(b.loot) == "table" and b.loot or {}) do
              if num(item) and item > 0 then be.loot[#be.loot + 1] = item; s.items[item] = true end
            end
            e.bosses[#e.bosses + 1] = b.enc
            s.bosses[b.enc] = be
          elseif b.enc == nil then
            e.named[b.name:lower()] = { name = b.name, conf = conf(b.conf or d.conf), optional = b.optional == true or nil }
          end
        end
      end
      s.dungeons[id] = e
    end
  end
  for slot, en in pairs(type(K.enchants) == "table" and K.enchants or {}) do
    if num(slot) and slot >= 1 and slot <= 19 and type(en) == "table" then
      local e = { slot = slot, conf = conf(en.conf), list = {}, kinds = kindSet(en.kinds) }
      for _, x in ipairs(type(en.list) == "table" and en.list or {}) do
        if type(x) == "table" and num(x.spell) and type(x.name) == "string" then
          e.list[#e.list + 1] = { spell = x.spell, name = x.name, ench = num(x.ench), kinds = kindSet(x.kinds) }
          s.spells[x.spell] = true
        end
      end
      s.enchants[slot] = e
    end
  end
  for l, v in pairs(type(K.xp) == "table" and K.xp or {}) do
    if num(l) and l >= 1 and l < 200 and num(v) and v > 0 then s.xp[l] = v end
  end
  for l, c in pairs(type(K.xpConf) == "table" and K.xpConf or {}) do if num(l) then s.xpConf[l] = conf(c) end end
  for id, f in pairs(type(K.factions) == "table" and K.factions or {}) do
    if num(id) and type(f) == "table" and type(f.name) == "string" then s.factions[id] = { id = id, name = f.name, conf = conf(f.conf) } end
  end
  -- (a seed that names nothing is none: the Guide says nothing shipped rather than "from research")
  if not (next(s.dungeons) or next(s.enchants) or next(s.xp) or next(s.factions)) then seed = false; return nil end
  seed = s
  return s
end
-- (the harness gives each pass its own seed)
function R.ResetSeed() seed = nil end

----------------------------------------------------------------------------
-- Rule 0: the seed is checked against the live client at login, after the roster, before the Guide is drawn, fifty
-- ids a frame so no frame stalls: the items with C_Item.GetItemInfoInstant (nothing back: the client lacks it), the
-- enchant recipes with C_Spell.DoesSpellExist, the factions with C_Reputation.GetFactionDataByID, the build with
-- GetBuildInfo (all four in Forever's generated API docs), each through C.Ask (Core.lua), so a call that throws or
-- gives a secret says nothing either way and is not counted, and a function the client lacks is recorded for /cute
-- api. A fact the client lacks is absent. If more than staleShare of what was asked is absent, or the client's major
-- version differs from the seed's, the whole seed is stale: it neither counts as missing nor recommends, and the
-- Guide says so. A new minor version or build alone is no verdict: the share of absent facts is the evidence that the
-- game changed. On a build other than the seed's, every beta fact counts as data until the guild sees it (the beta
-- proved nothing about this build)
----------------------------------------------------------------------------
local function major(b) return type(b) == "string" and b:match("^(%d+)%.") or nil end
-- each kind's question: the client's function, and what its first return says (true: it has it, false: it lacks it)
local ASK = {
  item = { "C_Item", "GetItemInfoInstant", function(v) return v ~= nil end },
  spell = { "C_Spell", "DoesSpellExist", function(v) if type(v) == "boolean" then return v end end },
  faction = { "C_Reputation", "GetFactionDataByID", function(v) return type(v) == "table" end },
}
R.KINDS = { "item", "spell", "faction" }
function R:CheckSeed()
  local s = R.Seed()
  if not s then self.check = { state = "done", total = 0, absent = 0, kinds = {}, missing = { item = {}, spell = {}, faction = {} } }; return self:Checked() end
  -- (looked up once: a function the client lacks is recorded once, and every id of its kind counts neither way)
  local fns = {}
  for kind, q in pairs(ASK) do fns[kind] = C.Api(q[1], q[2]) end
  local list = {}
  for _, kind in ipairs(R.KINDS) do
    local ids = {}
    for id in pairs(kind == "item" and s.items or (kind == "spell" and s.spells or s.factions)) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do list[#list + 1] = { kind, id } end
  end
  local chk = { state = "checking", total = 0, absent = 0, i = 0, kinds = {}, missing = { item = {}, spell = {}, faction = {} } }
  for _, kind in ipairs(R.KINDS) do chk.kinds[kind] = { n = 0, absent = 0 } end
  if C.Callable("GetBuildInfo") then
    local v, b = C.Get("GetBuildInfo")
    if type(v) == "string" and v ~= "" then chk.client = v .. ((type(b) == "string" and b ~= "") and ("." .. b) or "") end
  end
  self.check = chk
  local function step()
    for _ = 1, SLICE do
      chk.i = chk.i + 1
      local e = list[chk.i]
      if not e then return R:Checked() end
      local has
      local fn = fns[e[1]]
      if fn then
        local v, said = C.Ask(fn, e[2])
        if said then has = ASK[e[1]][3](v) end
      end
      if has ~= nil then
        local kd = chk.kinds[e[1]]
        kd.n, chk.total = kd.n + 1, chk.total + 1
        if not has then kd.absent, chk.absent = kd.absent + 1, chk.absent + 1; chk.missing[e[1]][e[2]] = true end
      end
    end
    C_Timer.After(0, C.Safe(step, "rules: rule 0"))
  end
  step()
end
-- Rule 0 done: the verdict kept for /cute diag, the model built, your Missing enchants asked again (the seed may count
-- now, or no longer), the Guide drawn
function R:Checked()
  local chk = self.check
  chk.state = "done"
  local k = known()
  if k then
    local st, why = R.SeedState()
    local s = R.Seed()
    k.seed = { state = st, why = why, build = s and s.build or nil, client = chk.client, total = chk.total, absent = chk.absent, at = C.Now() }
  end
  self:Rebuild()
  if C.Sample and C.Sample.started then C.Sample:Schedule("unenchanted"); C.Sample:Schedule("ready") end
  if C.UI and C.UI.Refresh then C.UI:Refresh() end
end
-- none (no seed shipped), checking (Rule 0 still running), fresh, stale; with stale, why in words
function R.SeedState()
  local s = R.Seed()
  if not s then return "none" end
  local chk = R.check
  if not chk or chk.state ~= "done" then return "checking" end
  local mine, theirs = major(chk.client), major(s.build)
  if mine and theirs and mine ~= theirs then
    return "stale", string.format("this client is build %s, the research %s, another major version", chk.client, s.build)
  end
  if chk.total > 0 and chk.absent / chk.total > R.Get("staleShare") + 1e-9 then
    local parts = {}
    for _, kind in ipairs(R.KINDS) do
      local kd = chk.kinds[kind]
      if kd and kd.n > 0 then parts[#parts + 1] = string.format("%s %d of %d", kind == "item" and "items" or (kind == "spell" and "enchants" or "factions"), kd.absent, kd.n) end
    end
    return "stale", string.format("%d%% of what it names is not in this client (%s)", math.floor(chk.absent * 100 / chk.total + 0.5), table.concat(parts, ", "))
  end
  return "fresh"
end
-- the seed may say what is missing and what to run: Rule 0 done and the seed not stale
function R.SeedUsable() return R.SeedState() == "fresh" end
-- the beta's findings count as research on any other build
function R.BetaAsData()
  local s, chk = R.Seed(), R.check
  return s ~= nil and chk ~= nil and chk.client ~= nil and s.build ~= nil and chk.client ~= s.build
end
local function base(c)
  if R.SeedState() == "stale" then return "stale" end
  if c == "beta" and R.BetaAsData() then return "data" end
  return c
end

----------------------------------------------------------------------------
-- the evidence: you, then every saved record that carries a GUID (one without would count its member twice once the
-- GUID came), one per GUID, with the discovered values (boss kills e<id>, dungeon entries i<id>, kill levels k<id>)
----------------------------------------------------------------------------
local DYN = "^[eik]%d+$"
function R.Members()
  local out, seen = {}, {}
  local me = C.MyGUID() or "me"
  local v = C.Sample and C.Sample.values or {}
  local dyn = {}
  for id, x in pairs(C.Char().counters) do if type(id) == "string" and id:match(DYN) and type(x) == "number" and x > 0 then dyn[id] = x end end
  out[1] = { guid = me, me = true, level = num(v.level), dyn = dyn, stats = v }
  seen[me] = true
  for key, e in pairs(CuteDB and CuteDB.roster or {}) do
    local st = type(e) == "table" and type(e.stats) == "table" and e.stats or nil
    local g = st and st.guid
    if type(g) == "string" and g ~= "" and not seen[g] and not C.Roster:IsSelfRecord(key, e) then
      seen[g] = true
      local d = {}
      for id, x in pairs(st) do if type(id) == "string" and type(x) == "number" and x > 0 and id:match(DYN) then d[id] = x end end
      out[#out + 1] = { guid = g, level = num(st.level), dyn = d, stats = st, key = key }
    end
  end
  return out
end

----------------------------------------------------------------------------
-- the rules, one function each
----------------------------------------------------------------------------
-- 1. Seen beats believed. A fact any member met is seen: who met it (by GUID, the earlier builds' too), how many, the
-- first time. The state words say "seen by N members" from then on, "from research" or "seen in the beta" before
function R.SeenBeatsBelieved(fact, now, old)
  old = type(old) == "table" and old or {}
  local who, n = {}, 0
  for g in pairs(type(old.who) == "table" and old.who or {}) do if n < WHO_CAP then who[g] = true; n = n + 1 end end
  for g in pairs(fact.seenNow or {}) do if not who[g] and n < WHO_CAP then who[g] = true; n = n + 1 end end
  fact.seenNow = nil
  fact.who, fact.n = who, n
  if fact.n > 0 or not fact.seeded then
    fact.at = old.at or now
    fact.state = "seen"
  end
end

-- 2. New things join. An instance entered or a boss killed that the seed lacks is added as seen: a dungeon or a raid
-- by the instance's label and kind (Sample.lua labels it on entry), a boss under the instance it was killed in. A boss
-- whose name is one the seed gives under that instance without an encounter id is the seed's, met at last: it joins as
-- the seed's, not as new
function R.NewThingsJoin(m, k)
  local labels, kinds, inst = k.labels or {}, k.kind or {}, k.inst or {}
  for id, kind in pairs(kinds) do
    if (kind == "party" or kind == "raid") and not m.dungeons[id] and type(labels["i" .. id]) == "string" then
      m.dungeons[id] = { id = id, name = labels["i" .. id], kind = kind, seeded = false, state = "seen", bosses = {} }
    end
  end
  local joined = {}
  for enc, i in pairs(inst) do
    local label = labels["e" .. enc]
    if num(enc) and not m.bosses[enc] and m.dungeons[i] and type(label) == "string" then
      local named = m.dungeons[i].named and m.dungeons[i].named[label:lower()]
      if named then
        m.bosses[enc] = { enc = enc, name = label, seedName = named.name ~= label and named.name or nil, inst = i, seeded = true,
          conf = named.conf, state = base(named.conf), optional = named.optional, loot = {} }
      else
        m.bosses[enc] = { enc = enc, name = label, inst = i, seeded = false, state = "seen", loot = {} }
      end
      joined[#joined + 1] = enc
    end
  end
  -- (after the seed's bosses, in the order the encounters are numbered)
  table.sort(joined)
  for _, enc in ipairs(joined) do
    local b = m.bosses[enc]
    local d = m.dungeons[b.inst]
    d.bosses[#d.bosses + 1] = enc
    b.order = 1000 + #d.bosses
  end
end

-- 3. Level ranges learn. A dungeon's range is the rangeLow to rangeHigh percentile of the levels members had at their
-- first kill of one of its bosses (each member once, their lowest), once rangeMembers distinct members have; until
-- then the seed's range stands. With no seed for it (none shipped, a stale one, or Rule 0 still asking) the levels
-- seen so far stand in, and say so. The percentiles set the tails aside: the lowest rangeLow and the highest
-- 1 - rangeHigh of the levels, each rounded half up, so five members at 10 % set one aside at either end and one
-- member boosted through at 12, or one farming it at 60, never stretches the range (where a tail rounds to nothing,
-- four members at 10 % or a 0 % an officer chose, the lowest or the highest level is the end; where nothing would be
-- left, the middle one)
local function percentiles(sorted, lo, hi)
  local n = #sorted
  local i, j = 1 + math.floor(lo * n + 0.5 + 1e-9), n - math.floor((1 - hi) * n + 0.5 + 1e-9)
  if i > j then i = math.floor((n + 1) / 2); j = i end
  return sorted[math.max(1, math.min(n, i))], sorted[math.max(1, math.min(n, j))]
end
function R.LevelRangesLearn(d, levels)
  local list = {}
  for _, l in pairs(levels or {}) do list[#list + 1] = l end
  table.sort(list)
  d.levels = #list
  local lo, hi = R.Get("rangeLow"), R.Get("rangeHigh")
  if lo > hi then lo, hi = hi, lo end
  if #list >= R.Get("rangeMembers") then
    d.min, d.max = percentiles(list, lo, hi)
    d.range = "learned"
  elseif d.seeded and d.seedMin and R.SeedUsable() then
    d.min, d.max, d.range = d.seedMin, d.seedMax, "seed"
  elseif #list > 0 then
    d.min, d.max, d.range = list[1], list[#list], "seen"
  else
    d.min, d.max, d.range = nil, nil, nil
  end
end

-- 4. Doubt, never delete. A seeded boss the guild's full runs of its dungeon never met is doubted: shown dim, "not
-- seen in N runs", never removed. A full run is a member who has killed every boss there the guild has seen, and the
-- guild has seen two or more (so no run that stopped short counts; the seed's order of the bosses says nothing of the
-- paths through a dungeon, and is not asked). While the guild has met only one boss there, every member who killed it
-- would pass for a full run, a first boss alone would doubt the rest, and nothing is doubted. (The first 0.5.0 build
-- did: a guild of nine that had killed only the Deadmines' first boss doubted the other three.) One seeded boss
-- missing from doubtRuns such runs is doubted; where several are missing, each takes
-- doubtRuns runs more before any is: a dungeon whose runs miss many of its bosses has paths and optional fights, not
-- that many bosses gone (three runs of Blackrock Depths to the Emperor that spare Moira and skip the Grim Guzzler miss
-- nine of its twenty-one, and would take twenty-seven). Never in a dungeon the seed marks as wings sharing one instance
-- (a run is one wing) nor for a boss it marks optional. A seeded enchant slot nobody has an enchant in
-- enchantDoubtDays after members at enchantDoubtLevel or more were first seen wearing items there is doubted and stops
-- counting as missing (R.SlotDoubted, which rule 5 asks)
function R.SlotDoubted(slot)
  local k = known()
  local watch = k and type(k.watch) == "table" and num(k.watch[slot]) or nil
  return watch ~= nil and C.Now() - watch >= R.Get("enchantDoubtDays") * DAY
end
function R.DoubtNeverDelete(m, members)
  if not R.SeedUsable() then return end
  local need = R.Get("doubtRuns")
  for _, d in pairs(m.dungeons) do
    if d.seeded and not d.wings then
      local met, open = {}, {}
      for _, enc in ipairs(d.bosses) do
        local b = m.bosses[enc]
        if b.state == "seen" then met[#met + 1] = enc
        elseif b.seeded and not b.optional and b.state ~= "stale" then open[#open + 1] = b end
      end
      if #met >= 2 and #open > 0 then
        local runs = 0
        for _, mem in ipairs(members) do
          local full = true
          for _, enc in ipairs(met) do if not mem.dyn["e" .. enc] then full = false; break end end
          if full then runs = runs + 1 end
        end
        for _, b in ipairs(open) do
          b.runs = runs
          if runs >= need * #open then b.state = "doubted" end
        end
      end
    end
  end
end

-- 5. Enchant slots. A slot counts as enchantable when one member has a permanent enchant there (Stats.lua learns
-- those, by slot and kind of item) or the seed says so (a recipe for it exists in Forever, on that kind of item where
-- the seed names kinds) for a character at enchantDoubtLevel or more: a character levelling through gear it outgrows
-- in a few levels is asked only for what the guild has actually enchanted. Missing enchants is the worn slots that
-- count, not enchanted. The seed counts only once Rule 0 has found it fresh, and not for a slot whose recipes the
-- client lacks or that the guild has doubted. level nil asks for the slot whatever the level (a member's list,
-- which their own client cut by their level). What the guild learns only ever widens the seed, never narrows it: the
-- seed's own word on a slot (SeedSlotState) is kept apart from what the guild has seen there, so one member's enchant
-- on a leather bracer leaves the seed counting a cloth one, and each enchant the seed lists is seen only once that
-- enchant was. (The first 0.5.0 build made the whole slot "seen" at the first enchant on any kind of item, and the
-- seed stopped counting every other kind there)
function R.SeedSlotState(slot)
  local s = R.Seed()
  local e = s and s.enchants[slot]
  if not e then return nil end
  if R.SeedState() == "stale" then return "stale" end
  if #e.list > 0 and R.check and R.check.state == "done" then
    local absent = 0
    for _, x in ipairs(e.list) do if R.check.missing.spell[x.spell] then absent = absent + 1 end end
    if absent == #e.list then return "absent" end
  end
  -- (an enchant there on any kind of item is the guild's play agreeing with the seed: no doubt)
  if R.SlotDoubted(slot) and not C.Stats.EnchantLearned(slot) then return "doubted" end
  return base(e.conf)
end
-- a slot as the model and /cute diag show it: seen once the guild has an enchant there on any kind of item, else the
-- seed's word; nil where the seed has no enchant for it
function R.SlotState(slot)
  local st = R.SeedSlotState(slot)
  if st ~= nil and C.Stats.EnchantLearned(slot) then return "seen" end
  return st
end
function R.SeedEnchantable(slot, kind, level)
  if not R.SeedUsable() then return false end
  if level ~= nil and not (num(level) and level >= R.Get("enchantDoubtLevel")) then return false end
  local st = R.SeedSlotState(slot)
  if st == nil or st == "stale" or st == "absent" or st == "doubted" then return false end
  local kinds = R.Seed().enchants[slot].kinds
  return kind == nil or kinds == nil or kinds[kind] == true
end
-- the enchants the seed lists for a slot that take a kind of item (kind nil: all of them), each with its state: seen
-- (the guild has that enchant on an item), absent (the client lacks the recipe), else the seed's word on the slot
-- (data, beta, stale, doubted), whatever the guild has put on other kinds of item there. An enchant takes a kind where
-- the seed names its kinds and the kind is one of them. One the seed names no kinds for takes any armour its slot
-- takes (every kind of armour a slot holds takes the same enchants), but is not placed in the hands' slots, where a
-- two-hander, a one-hander, a shield and a book held in the off hand take different ones: those are counted instead,
-- the second return, so the Guide never offers a two-hander's enchant for a dagger or an off-hand's for a shield
local HANDS = { [16] = true, [17] = true, [18] = true }
function R.SlotEnchants(slot, kind)
  local s = R.Seed()
  local e = s and s.enchants[slot]
  if not e then return {}, 0 end
  local st = R.SeedSlotState(slot)
  local out, unplaced = {}, 0
  for _, x in ipairs(e.list) do
    local state = st
    if R.check and R.check.missing.spell[x.spell] then state = "absent"
    elseif x.ench and C.Stats.EnchantIdSeen(slot, x.ench) > 0 then state = "seen" end
    local takes
    if kind == nil then takes = true
    elseif x.kinds then takes = x.kinds[kind] == true
    elseif HANDS[slot] then takes = false; if state ~= "absent" then unplaced = unplaced + 1 end
    else takes = e.kinds == nil or e.kinds[kind] == true end
    if takes then out[#out + 1] = { name = x.name, spell = x.spell, ench = x.ench, state = state, n = x.ench and C.Stats.EnchantIdSeen(slot, x.ench) or 0 } end
  end
  table.sort(out, function(a, b) if (a.state == "seen") ~= (b.state == "seen") then return a.state == "seen" end return a.name < b.name end)
  return out, unplaced
end
-- the clock of rule 4 for enchant slots: the first time a member at enchantDoubtLevel or more was seen wearing an item
-- in a slot (your own gear; a member's empty slots, which cover every slot but the off hand and the ranged slot)
local function watch(k, members)
  k.watch = type(k.watch) == "table" and k.watch or {}
  local lvl, now = R.Get("enchantDoubtLevel"), C.Now()
  for _, mem in ipairs(members) do
    if mem.level and mem.level >= lvl then
      if mem.me then
        local g = C.Stats.Gear and C.Stats.Gear() or nil
        if g then for slot in pairs(g.slot) do k.watch[slot] = k.watch[slot] or now end end
      elseif type(mem.stats.empty_slots) == "table" then
        for slot = 1, 16 do if slot ~= 4 and not mem.stats.empty_slots[slot] then k.watch[slot] = k.watch[slot] or now end end
      end
    end
  end
end

-- 6. The XP curve learns. Each member reports UnitXPMax at each level they reach (the hidden xpmax stat, "level:max");
-- once xpAgree members agree on a level, that value replaces the seed's. A sample that matches the seed makes it seen;
-- with no seed for a level (or a stale one) the value most members reported stands. Hours to 60 and the Guide's pace
-- use the curve, levels nobody reported estimated from their neighbours (XPCurve)
function R.LearnXP(level, who, max)
  local k = known()
  level, max = num(tonumber(level)), num(tonumber(max))
  if not (k and level and max and level >= 1 and level < 200 and max > 0 and max < 2 ^ 31) or type(who) ~= "string" or who == "" then return end
  k.xp = type(k.xp) == "table" and k.xp or {}
  local t = k.xp[level]
  if type(t) ~= "table" then t = {}; k.xp[level] = t end
  if t[who] == max then return end
  if t[who] == nil and count(t) >= WHO_CAP then return end
  t[who] = max
  R:Dirty()
end
-- "38:66200" from a record, and back
function R.ParseXP(text)
  if type(text) ~= "string" then return nil end
  local l, m = text:match("^(%d+):(%d+)$")
  return tonumber(l), tonumber(m)
end
function R.XPCurveLearns(level)
  local k = known()
  local samples = k and type(k.xp) == "table" and k.xp[level] or nil
  local votes, best, bestN = {}, nil, 0
  for _, v in pairs(type(samples) == "table" and samples or {}) do
    if num(v) then
      votes[v] = (votes[v] or 0) + 1
      if votes[v] > bestN or (votes[v] == bestN and v > best) then best, bestN = v, votes[v] end
    end
  end
  local s = R.Seed()
  local sv = s and R.SeedUsable() and s.xp[level] or nil
  if best and bestN >= R.Get("xpAgree") then return best, "seen", bestN, sv end
  if sv then
    if votes[sv] then return sv, "seen", votes[sv], sv end
    return sv, base(s.xpConf[level] or "data"), 0, sv
  end
  if best then return best, "seen", bestN end
  return nil
end
-- the XP each level takes, 1 to the cap (60 at least): learned or seeded, the gaps estimated, a straight line between
-- two known levels and the last two's step past them; nothing where fewer than two levels are known
local curveCache, curveAt
function R.XPCurve()
  if curveCache and curveAt == R.version then return curveCache end
  local top = math.max(R.Cap(), 60) - 1
  local out, pts = {}, {}
  for l = 1, top do
    local v, state, n = R.XPCurveLearns(l)
    if v then out[l] = { v = v, state = state, n = n }; pts[#pts + 1] = l end
  end
  if #pts >= 2 then
    local j = 1
    for l = 1, top do
      while pts[j + 1] and pts[j + 1] < l do j = j + 1 end
      if not out[l] then
        local lo, hi = pts[j], pts[j + 1]
        local v
        if lo < l and hi and hi > l then v = out[lo].v + (out[hi].v - out[lo].v) * (l - lo) / (hi - lo)
        elseif l > pts[#pts] then
          local a, b = pts[#pts - 1], pts[#pts]
          v = out[b].v + math.max(0, (out[b].v - out[a].v) / (b - a)) * (l - b)
        else
          local a, b = pts[1], pts[2]
          v = math.max(1, out[a].v - math.max(0, (out[b].v - out[a].v) / (b - a)) * (a - l))
        end
        out[l] = { v = math.floor(v + 0.5), state = "estimated" }
      end
    end
  end
  curveCache, curveAt = out, R.version
  return out
end
-- the XP left from (lvl, xp, max) to the target level (60 where none is given): this level's rest and every level
-- ahead; nil where the curve does not reach
function R.XPLeft(lvl, xp, max, target)
  target = target or 60
  if not (num(lvl) and num(xp) and num(max)) then return nil end
  if lvl >= target then return 0 end
  local curve = R.XPCurve()
  local left = math.max(0, max - xp)
  for l = lvl + 1, target - 1 do
    local e = curve[l]
    if not e then return nil end
    left = left + e.v
  end
  return left
end

-- 7. The level cap is the game's: GetMaxPlayerLevel and GetMaxLevelForPlayerExpansion, the lower of the two that
-- reads ten or more (as QuestBank reads them); the seed's 60 where neither does. The highest level any member has
-- reached is never above it: a member past it means the game lets them go further
function R.LevelCap()
  local cap
  for _, name in ipairs({ "GetMaxPlayerLevel", "GetMaxLevelForPlayerExpansion" }) do
    if C.Callable(name) then
      local v = C.Num(name)
      if v and v >= 10 and (not cap or v < cap) then cap = v end
    end
  end
  local s = R.Seed()
  cap = cap or (s and s.cap) or 60
  for _, r in ipairs(C.Roster:Rows()) do if num(r.level) and r.level > cap then cap = r.level end end
  return math.floor(cap)
end
function R.Cap()
  local key = R.version .. ":" .. C.Roster.version
  if R.capAt ~= key or not R.cap then R.cap, R.capAt = R.LevelCap(), key end
  return R.cap
end

-- 8. Loot learns. The items in the first corpse's loot window this character opens within a minute of a boss kill,
-- in the same instance, that holds something green or better (Sample.lua reads the window, never loots from it; a
-- container opened from the bags is no corpse), are that boss's loot as seen, told to the guild in the labels
-- message; seeded loot not seen stays data, and once the guild has killed the boss lootDoubtKills times the tooltip
-- says it has not been seen in that many kills (a drop can be rare: never doubted)
function R.LearnLoot(enc, ids, own)
  local k = known()
  if not (k and num(enc)) or type(ids) ~= "table" then return false end
  k.loot = type(k.loot) == "table" and k.loot or {}
  local rec = k.loot[enc]
  if type(rec) ~= "table" then rec = { items = {}, mine = {} }; k.loot[enc] = rec end
  rec.items = type(rec.items) == "table" and rec.items or {}
  rec.mine = type(rec.mine) == "table" and rec.mine or {}
  local new = false
  for _, id in ipairs(ids) do
    if num(id) and id > 0 and id < 2 ^ 31 then
      if rec.items[id] == nil and count(rec.items) < LOOT_CAP then rec.items[id] = C.Now(); new = true end
      if own and rec.items[id] and not rec.mine[id] then rec.mine[id] = true; new = true end
    end
  end
  if new then R:Dirty() end
  return new
end
-- what this character saw drop from a boss, for the labels message: item ids in base 36 joined by dots
function R.LootText(enc)
  local k = known()
  local rec = k and type(k.loot) == "table" and k.loot[enc]
  if type(rec) ~= "table" or type(rec.mine) ~= "table" then return nil end
  local ids = {}
  for id in pairs(rec.mine) do if num(id) then ids[#ids + 1] = id end end
  if #ids == 0 then return nil end
  table.sort(ids)
  local parts = {}
  for i = 1, math.min(#ids, 24) do parts[i] = C.Comm.b36(ids[i]) end
  return table.concat(parts, ".")
end
function R.LootLearns(m, k)
  local loot = type(k.loot) == "table" and k.loot or {}
  local need = R.Get("lootDoubtKills")
  for enc, b in pairs(m.bosses) do
    local rec = type(loot[enc]) == "table" and type(loot[enc].items) == "table" and loot[enc].items or {}
    for id, at in pairs(rec) do if num(id) then b.loot[id] = "seen"; b.lootAt = b.lootAt or {}; b.lootAt[id] = at end end
    if b.seeded and (b.kills or 0) >= need then b.lootQuiet = true end
  end
end

----------------------------------------------------------------------------
-- the model: the seed, Rule 0's verdict and the guild's play, built again at login and a few seconds after anything
-- the rules weigh changes. CuteDB.known.model = { seed, dungeons, bosses, enchants, xp, factions }
----------------------------------------------------------------------------
function R:Rebuild()
  local k = known()
  if not k then return end
  local s = R.Seed()
  local now = C.Now()
  local old = type(k.model) == "table" and k.model or {}
  local oldOf = function(t, id) return type(old[t]) == "table" and old[t][id] or nil end
  local st, why = R.SeedState()
  local missing = (self.check and self.check.missing) or { item = {}, spell = {}, faction = {} }
  local m = { at = now, seed = st, why = why, dungeons = {}, bosses = {}, enchants = {}, xp = {}, factions = {} }
  -- (a dungeon or boss is shown by the name this game gives it once a member met it, the discoveries' label; the seed's
  -- name, where it differs, goes in its tooltip)
  local labels = type(k.labels) == "table" and k.labels or {}
  local function named(seedName, label)
    if type(label) == "string" and label ~= "" and label ~= seedName then return label, seedName end
    return seedName, nil
  end
  if s then
    for id, d in pairs(s.dungeons) do
      local name, seedName = named(d.name, labels["i" .. id])
      local dm = { id = id, name = name, seedName = seedName, kind = d.kind, seeded = true, new = d.new, conf = d.conf, state = base(d.conf),
        seedMin = d.min, seedMax = d.max, bosses = {}, named = d.named, wings = d.wings }
      m.dungeons[id] = dm
      for _, enc in ipairs(d.bosses) do
        local b = s.bosses[enc]
        local bname, bseed = named(b.name, labels["e" .. enc])
        local bm = { enc = enc, name = bname, seedName = bseed, inst = id, order = b.order, seeded = true, conf = b.conf, state = base(b.conf),
          optional = b.optional, loot = {} }
        for _, item in ipairs(b.loot) do bm.loot[item] = missing.item[item] and "absent" or base(b.conf) end
        m.bosses[enc] = bm
        dm.bosses[#dm.bosses + 1] = enc
      end
    end
  end
  R.NewThingsJoin(m, k)
  -- what the guild met, member by member
  local members = R.Members()
  local levels = {}
  for _, mem in ipairs(members) do
    for id, v in pairs(mem.dyn) do
      local p, n = id:sub(1, 1), tonumber(id:sub(2))
      if p == "i" then
        local d = m.dungeons[n]
        if d then d.seenNow = d.seenNow or {}; d.seenNow[mem.guid] = true end
      elseif p == "e" then
        local b = m.bosses[n]
        if b then
          b.seenNow = b.seenNow or {}; b.seenNow[mem.guid] = true
          b.kills = (b.kills or 0) + v
          local d = m.dungeons[b.inst]
          if d then d.seenNow = d.seenNow or {}; d.seenNow[mem.guid] = true end
        end
      elseif p == "k" then
        local b = m.bosses[n]
        local inst = b and b.inst or (type(k.inst) == "table" and k.inst[n]) or nil
        if inst and m.dungeons[inst] then
          levels[inst] = levels[inst] or {}
          if not levels[inst][mem.guid] or v < levels[inst][mem.guid] then levels[inst][mem.guid] = v end
        end
      end
    end
  end
  for id, d in pairs(m.dungeons) do R.SeenBeatsBelieved(d, now, oldOf("dungeons", id)) end
  for enc, b in pairs(m.bosses) do R.SeenBeatsBelieved(b, now, oldOf("bosses", enc)) end
  for id, d in pairs(m.dungeons) do R.LevelRangesLearn(d, levels[id]) end
  R.DoubtNeverDelete(m, members)
  R.LootLearns(m, k)
  -- the enchant slots: the seed's and the guild's
  watch(k, members)
  for slot = 1, 19 do
    local state = R.SlotState(slot)
    local learned = C.Stats.EnchantLearned(slot)
    if state or learned then
      m.enchants[slot] = { slot = slot, seeded = state ~= nil, state = state or "seen", n = C.Stats.EnchantSeen(slot), watch = num(k.watch[slot]) }
    end
  end
  -- the XP curve, and the cap it runs to
  self.version = self.version + 1
  local top = math.max(R.Cap(), 60) - 1
  for l = 1, top do
    local v, state, n, sv = R.XPCurveLearns(l)
    if v then m.xp[l] = { v = v, state = state, n = n, seed = sv } end
  end
  -- the factions: seen once on a reputation list (yours, or a member's label), absent where the client lacks them
  if s then
    for id, f in pairs(s.factions) do
      local seen = type(k.labels) == "table" and k.labels["f" .. id] ~= nil
      m.factions[id] = { id = id, name = f.name, state = seen and "seen" or (missing.faction[id] and "absent" or base(f.conf)) }
    end
  end
  k.model = m
  self.model = m
  self.version = self.version + 1
  return m
end

-- the guild's play changed something the rules weigh: built again three seconds on (a burst of records builds once);
-- the Guide draws again only when it is the page open
function R:Dirty()
  self.version = self.version + 1
  if self.due or not self.started then return end
  self.due = true
  C_Timer.After(3, C.Safe(function()
    R.due = false
    R:Rebuild()
    if C.UI and C.UI.page == "guide" and C.UI.Refresh then C.UI:Refresh() end
  end, "rules: rebuild"))
end
-- a member's values arrived (Roster.lua): their XP sample learned at once, the model built again when it weighs them
local WEIGH = { level = true, empty_slots = true, ench_kinds = true, xpmax = true }
function R:Observe(stats, kv)
  local g = type(stats) == "table" and stats.guid or nil
  if kv.xpmax ~= nil and type(g) == "string" and g ~= "" then
    local l, mx = R.ParseXP(stats.xpmax)
    if l then R.LearnXP(l, g, mx) end
  end
  for id in pairs(kv) do
    if WEIGH[id] or (type(id) == "string" and id:match(DYN)) then return self:Dirty() end
  end
end

-- at login: the XP samples the saved records carry (a member's level at the time), then Rule 0, which builds the model
function R:Start()
  if self.started then return end
  self.started = true
  for key, e in pairs(CuteDB.roster or {}) do
    local st = type(e) == "table" and type(e.stats) == "table" and e.stats or nil
    if st and type(st.guid) == "string" and st.guid ~= "" and not C.Roster:IsSelfRecord(key, e) then
      local l, mx = R.ParseXP(st.xpmax)
      if l then R.LearnXP(l, st.guid, mx) end
    end
  end
  self:CheckSeed()
end

----------------------------------------------------------------------------
-- what the model says, in words, for the Guide's lines and tooltips
----------------------------------------------------------------------------
local function members(n) return n == 1 and "1 member" or (n .. " members") end
function R.Words(fact)
  if type(fact) ~= "table" then return "" end
  local st = fact.state
  if st == "seen" then return (fact.n or 0) > 0 and ("seen by " .. members(fact.n)) or "seen in play" end
  if st == "beta" then return "seen in the beta" end
  if st == "data" then return "from research" end
  if st == "doubted" then return fact.runs and ("doubted: not seen in " .. fact.runs .. " runs") or "doubted" end
  if st == "absent" then return "not in this client" end
  if st == "stale" then return "from research this game no longer matches" end
  if st == "estimated" then return "estimated" end
  return st or ""
end
-- a dungeon's range in words: "18-23", and where it comes from
function R.RangeWords(d)
  if not (d and d.min) then return "?", "not known yet: the guild's kills will tell" end
  local r = d.min == d.max and tostring(d.min) or (d.min .. "-" .. d.max)
  if d.range == "learned" then return r, "learned from " .. members(d.levels) end
  if d.range == "seen" then return r, "killed at these levels by " .. members(d.levels) end
  return r, d.state == "beta" and "the beta's range" or "the research's range"
end
function R.Model()
  if not R.model then R:Rebuild() end
  return R.model
end

-- the dungeons for a level: the ones whose range holds it, and the ones opening within guideAhead levels above it; each
-- sorted by its lowest level, then name
function R.DungeonsFor(level)
  local m = R.Model()
  local now, soon = {}, {}
  if not (m and num(level)) then return now, soon end
  local ahead = R.Get("guideAhead")
  for _, d in pairs(m.dungeons) do
    if d.min and d.state ~= "stale" then
      if d.min <= level and level <= d.max then now[#now + 1] = d
      elseif d.min > level and d.min <= level + ahead then soon[#soon + 1] = d end
    end
  end
  local function order(a, b) if a.min ~= b.min then return a.min < b.min end return a.name < b.name end
  table.sort(now, order)
  table.sort(soon, order)
  return now, soon
end

-- what the guild's play changed from the seed, for the officers: { { what, detail, kind, names }, ... } in a fixed
-- order (names: what a line's tooltip lists). With no research to weigh the play against (none shipped, or a stale
-- seed) nothing is a change from it: the list is what the guild learned, each dungeon or raid it met once with its
-- bosses counted on the line and named in the tooltip, the ranges it learned, the enchant slots it found. (The first
-- 0.5.0 build called that "13 changes from the research" and gave every boss a line of its own)
function R.Changes()
  local m = R.Model()
  local out = {}
  if not m then return out end
  local function add(what, detail, kind, names) out[#out + 1] = { what = what, detail = detail or "", kind = kind, names = names } end
  local st, why = R.SeedState()
  local research = st ~= "stale" and st ~= "none"
  if st == "stale" then add("The research is stale", why, "seed")
  elseif st == "none" then add("No research shipped with this copy", "everything here was learned in play", "seed") end
  local chk = R.check
  if st == "fresh" and chk and chk.absent > 0 then
    local parts = {}
    for _, kind in ipairs(R.KINDS) do
      local kd = chk.kinds[kind]
      if kd and kd.absent > 0 then parts[#parts + 1] = kd.absent .. " " .. (kind == "item" and "items" or (kind == "spell" and "enchants" or "factions")) end
    end
    add("Not in this client", table.concat(parts, ", "), "absent")
  end
  local function byName(list) table.sort(list, function(a, b) if a.name == b.name then return (a.id or a.enc or 0) < (b.id or b.enc or 0) end return a.name < b.name end) return list end
  local function met(f) return not f.seeded or (f.n or 0) > 0 end
  local list = {}
  if research then
    for _, d in pairs(m.dungeons) do if not d.seeded then list[#list + 1] = d end end
    for _, d in ipairs(byName(list)) do add("New " .. (d.kind == "raid" and "raid" or "dungeon") .. ": " .. d.name, R.Words(d), "new") end
    list = {}
    for _, b in pairs(m.bosses) do if not b.seeded then list[#list + 1] = b end end
    for _, b in ipairs(byName(list)) do add("New boss: " .. b.name, "in " .. ((m.dungeons[b.inst] or {}).name or "?") .. ", " .. R.Words(b), "new") end
  else
    for _, d in pairs(m.dungeons) do if met(d) then list[#list + 1] = d end end
    for _, d in ipairs(byName(list)) do
      local names = {}
      for _, enc in ipairs(d.bosses) do local b = m.bosses[enc]; if met(b) then names[#names + 1] = b.name end end
      local bosses = #names == 1 and "1 boss, " or (#names > 1 and (#names .. " bosses, ") or "")
      add((d.kind == "raid" and "Raid: " or "Dungeon: ") .. d.name, bosses .. R.Words(d), "learned", names)
    end
  end
  list = {}
  for _, d in pairs(m.dungeons) do if d.range == "learned" and (not research or d.seedMin ~= d.min or d.seedMax ~= d.max) then list[#list + 1] = d end end
  for _, d in ipairs(byName(list)) do
    local was = (research and d.seedMin) and (" (research " .. d.seedMin .. "-" .. d.seedMax .. ")") or ""
    add("Range learned: " .. d.name, d.min .. "-" .. d.max .. was .. ", from " .. members(d.levels), "range")
  end
  list = {}
  for _, b in pairs(m.bosses) do if b.state == "doubted" then list[#list + 1] = b end end
  for _, b in ipairs(byName(list)) do add("Doubted: " .. b.name, "in " .. ((m.dungeons[b.inst] or {}).name or "?") .. ", not seen in " .. (b.runs or 0) .. " runs", "doubted") end
  for slot = 1, 19 do
    local e = m.enchants[slot]
    local name = C.Stats.SLOT[slot] or ("Slot " .. slot)
    if e and e.state == "doubted" then add("Doubted: " .. name .. " enchants", "none seen in " .. R.Get("enchantDoubtDays") .. " days of members at " .. R.Get("enchantDoubtLevel") .. " or more", "doubted")
    elseif e and research and not e.seeded then add("New enchant slot: " .. name, "seen on " .. members(e.n or 0), "new")
    elseif e and not research and e.state == "seen" then add("Enchant slot: " .. name, "seen on " .. members(e.n or 0), "learned") end
  end
  for l = 1, 199 do
    local x = m.xp[l]
    if x and x.seed and x.state == "seen" and x.v ~= x.seed then
      add("XP to reach " .. (l + 1) .. ": " .. x.v, "research " .. x.seed .. ", from " .. members(x.n or 0), "xp")
    end
  end
  return out
end

-- one line for /cute diag: the seed's state and why, what Rule 0 asked, how many facts are in each state
function R.Report()
  local s = R.Seed()
  local st, why = R.SeedState()
  if not s then return "seed: none shipped; every rule runs on the guild's play" end
  local m = R.model
  local states = {}
  local function tally(st2) if st2 then states[st2] = (states[st2] or 0) + 1 end end
  if m then
    for _, d in pairs(m.dungeons) do tally(d.state) end
    for _, b in pairs(m.bosses) do tally(b.state); for _, ls in pairs(b.loot) do tally(ls) end end
    for _, e in pairs(m.enchants) do tally(e.state) end
    for _, x in pairs(m.xp) do tally(x.state) end
    for _, f in pairs(m.factions) do tally(f.state) end
  end
  local parts = {}
  for _, name in ipairs({ "data", "beta", "seen", "doubted", "absent", "stale" }) do parts[#parts + 1] = name .. " " .. (states[name] or 0) end
  local chk = R.check or {}
  local asked = {}
  for _, kind in ipairs(R.KINDS) do
    local kd = chk.kinds and chk.kinds[kind]
    if kd then asked[#asked + 1] = string.format("%s %d of %d", kind == "item" and "items" or (kind == "spell" and "enchants" or "factions"), kd.absent, kd.n) end
  end
  local build = (s.build or "?") .. (chk.client and (chk.client ~= s.build and (" (this client " .. chk.client .. (R.BetaAsData() and ": the beta's read as research)" or ")")) or " (this client too)") or "")
  return string.format("seed: %s%s | build %s | absent: %s | %s", st, why and (" (" .. why .. ")") or "", build,
    #asked > 0 and table.concat(asked, ", ") or "nothing asked yet", table.concat(parts, ", "))
end

-- /cute rules: each threshold, its value and who set it
function R.RulesReport()
  local out = {}
  for _, t in ipairs(R.TUNE) do
    local by = R.SetBy(t[1])
    out[#out + 1] = string.format("%s (%s): %s, %s", t[2], t[1], R.Show(t[1]), by and ("set by " .. R.WhoName(by)) or "the default")
  end
  return out
end
